input.sparql:
SELECT ?zone ?zoneLabel ?r where {
  ?z a brick:Zone .
  ?z brick:hasLocation ?z2 .
  OPTIONAL { ?z rdfs:label ?zoneLabel . }
} LIMIT 50

SELECT ?x ?p ?o WHERE {
  ?x brick:hasLocation ?y .
  ?y ref:hasTimeseriesId ?o .
  ?y brick:hasPoint ?x .
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?room ?zone WHERE {
  ?room brick:isPartOf ?zone .
  FILTER (str(?zone) LIKE "%F3%")
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?room ?z WHERE {
  ?z brick:hasPart ?room .
  FILTER (str(?z) LIKE "%F3%")
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?room ?z WHERE {
  ?z brick:hasPart ?room .
  ?room brick:hasPoint ?p .
  ?p a brick:Occupancy_Sensor .
}

SELECT ?s ?p WHERE {
  ?s brick:isPointOf ?x .
  ?x brick:isPartOf ?zone .
  ?s a brick:Occupancy_Sensor .
  ?s ref:hasTimeseriesId ?p
}

SELECT ?s ?tssid ?label ?room WHERE {
  ?s brick:isPointOf ?room .
  ?s a brick:Air_Temperature_Sensor .
  ?s ref:hasTimeseriesId ?tssid .
  ?room ?r ?o .
  OPTIONAL { ?s rdfs:label ?label }
  VALUES ?room {
    <http://buildgraph.org/BG_large_office_2004_0000#Room_F3_R001>
    <http://buildgraph.org/BG_large_office_2004_0000#Room_F3_R003>
    <http://buildgraph.org/BG_large_office_2004_0000#Room_F3_R005>
  }
  OPTIONAL { ?room rdfs:label ?label }
}
